  (* [comment removed for export] *)
  Lemma kn_blkA_ok : forall vals ebs Mx v n u,
    let E := Env (vals_ev vals) ebs in
    vals_ev vals v = Z_to_bv 64 u -> vals_ev vals 0 = sp0 ->
